import type { Carrier, Recipient, ServiceLevel } from '../types.ts';
import { HttpError } from './http.ts';
import { INVALID_TRACKING_NUMBER, shipmentBodySchema } from './schemas.ts';

export interface ShipmentInput {
  trackingNumber: string;
  carrier: Carrier;
  serviceLevel: ServiceLevel;
  recipient: Recipient;
}

/** Validates the body of POST /shipments (and the rows of POST /import) against the zod schema. */
export function validateShipmentInput(body: unknown): ShipmentInput {
  const parsed = shipmentBodySchema.safeParse(body);
  if (!parsed.success) {
    const issue = parsed.error.issues[0]!;
    const params = (issue as { params?: { kind?: string } }).params;
    if (params?.kind === INVALID_TRACKING_NUMBER) {
      throw new HttpError(400, 'INVALID_TRACKING_NUMBER', issue.message);
    }
    throw new HttpError(400, 'VALIDATION_FAILED', issue.message);
  }
  const { tracking_number, carrier, service_level, recipient } = parsed.data;
  const { phone, ...rest } = recipient;
  return {
    trackingNumber: tracking_number,
    carrier: carrier as Carrier,
    serviceLevel: service_level as ServiceLevel,
    recipient: { ...rest, ...(phone ? { phone } : {}) },
  };
}
