+import assert from 'node:assert/strict';
+import { describe, it } from 'node:test';
+import { HttpError } from '../src/lib/http.ts';
+import { shipmentBodySchema } from '../src/lib/schemas.ts';
+import { validateShipmentInput } from '../src/lib/validate.ts';
+import { validShipment } from './helpers.ts';
+
+function failure(body: unknown): HttpError {
+  try {
+    validateShipmentInput(body);
+  } catch (err) {
+    assert.ok(err instanceof HttpError);
+    return err;
+  }
+  assert.fail('expected validation to fail');
+}
+
+describe('shipment body schema', () => {
+  it('normalises a valid body', () => {
+    const input = validateShipmentInput(
+      validShipment({ tracking_number: ' rr123456785at ', carrier: 'atp', recipient: { name: ' A ', street: 's', zip: '1', city: 'c', country: 'de', phone: ' ' } }),
+    );
+    assert.equal(input.trackingNumber, 'RR123456785AT');
+    assert.equal(input.carrier, 'ATP');
+    assert.equal(input.serviceLevel, 'standard');
+    assert.deepEqual(input.recipient, { name: 'A', street: 's', zip: '1', city: 'c', country: 'DE' });
+  });
+
+  it('defaults the country to AT', () => {
+    const r = shipmentBodySchema.parse(validShipment({ recipient: { name: 'A', street: 's', zip: '1', city: 'c' } })).recipient;
+    assert.equal(r.country, 'AT');
+  });
+
+  it('rejects non-objects', () => {
+    for (const body of [null, [], 'x', 5]) {
+      const err = failure(body);
+      assert.equal(err.code, 'VALIDATION_FAILED');
+      assert.equal(err.message, 'body must be a JSON object');
+    }
+  });
+
+  it('reports missing fields', () => {
+    assert.equal(failure({}).message, 'tracking_number is required');
+    assert.equal(failure(validShipment({ recipient: undefined })).message, 'recipient is required');
+    assert.equal(
+      failure(validShipment({ recipient: { name: ' ', street: 's', zip: '1', city: 'c' } })).message,
+      'recipient.name is required',
+    );
+  });
+
+  it('rejects unknown carriers and service levels', () => {
+    assert.match(failure(validShipment({ carrier: 'FEDEX' })).message, /^carrier must be one of ATP, DHL/);
+    assert.match(failure(validShipment({ service_level: 'warp' })).message, /^service_level must be one of economy/);
+  });
+
+  it('keeps the INVALID_TRACKING_NUMBER code for a bad ATP check digit', () => {
+    const err = failure(validShipment({ tracking_number: 'RR123456780AT' }));
+    assert.equal(err.status, 400);
+    assert.equal(err.code, 'INVALID_TRACKING_NUMBER');
+    assert.match(err.message, /Prüfziffer/);
+  });
+});
